import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"DingTalk Channel Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/channels/dingtalk.md","filePath":"integrations/channels/dingtalk.md","lastUpdated":1790952322000}'),o={name:"integrations/channels/dingtalk.md"};function r(l,e,s,h,d,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="dingtalk-channel-configuration" tabindex="-1">DingTalk Channel Configuration <a class="header-anchor" href="#dingtalk-channel-configuration" aria-label="Permalink to &quot;DingTalk Channel Configuration&quot;">​</a></h1><p>Connect your Memoh bot to DingTalk for private and group chats: inbound events arrive over DingTalk&#39;s Stream mode, and replies and media are sent through DingTalk&#39;s official APIs.</p><div class="warning custom-block"><p class="custom-block-title">Limits</p><ul><li>Responses are delivered as complete messages; DingTalk output is not streamed token by token.</li></ul></div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Access to your organization&#39;s DingTalk developer platform, with permission to create apps.</li><li>No public callback URL is required: Memoh receives inbound events over a DingTalk Stream connection that it maintains automatically.</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-create-a-dingtalk-app" tabindex="-1">1. Create a DingTalk app <a class="header-anchor" href="#_1-create-a-dingtalk-app" aria-label="Permalink to &quot;1. Create a DingTalk app&quot;">​</a></h3><p>In the DingTalk developer platform for your organization:</p><ol><li>Create or choose the app that will act as the bot.</li><li>Enable the bot / messaging capability for that app.</li><li>Copy the <strong>App Key</strong> and <strong>App Secret</strong>.</li><li>Grant the app message permissions and publish it in your organization so end users can reach it.</li></ol><h3 id="_2-add-the-channel-in-memoh" tabindex="-1">2. Add the channel in Memoh <a class="header-anchor" href="#_2-add-the-channel-in-memoh" aria-label="Permalink to &quot;2. Add the channel in Memoh&quot;">​</a></h3><p>In Memoh:</p><ol><li>Open the bot&#39;s <strong>Platforms</strong> tab.</li><li>Click <strong>Add Channel</strong> and choose <strong>DingTalk</strong>.</li><li>Fill in <strong>App Key</strong> and <strong>App Secret</strong>.</li><li>Click <strong>Save and Enable</strong>.</li></ol><p>Memoh maintains the DingTalk Stream connection automatically — there is no webhook callback URL to paste.</p><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;Credentials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><strong>App Key</strong></td><td>Yes</td><td>The DingTalk app&#39;s key, copied from the app&#39;s credentials in the DingTalk developer platform.</td></tr><tr><td><strong>App Secret</strong></td><td>Yes</td><td>The DingTalk app&#39;s secret, copied from the same place.</td></tr></tbody></table><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p>Send <code>/help</code> to the bot in a private chat, or @mention it in a group chat with <code>/help</code>. The bot replies with its command list, which confirms the channel is working.</p><h2 id="group-chats" tabindex="-1">Group chats <a class="header-anchor" href="#group-chats" aria-label="Permalink to &quot;Group chats&quot;">​</a></h2><p>The bot works in DingTalk group chats: @mention it in a supported group to trigger a reply.</p><h2 id="disable-and-rotate-credentials" tabindex="-1">Disable and rotate credentials <a class="header-anchor" href="#disable-and-rotate-credentials" aria-label="Permalink to &quot;Disable and rotate credentials&quot;">​</a></h2><p>Disable or remove the channel at any time from the bot&#39;s <strong>Platforms</strong> tab. To rotate credentials, update <strong>App Key</strong> / <strong>App Secret</strong> in the same panel and save.</p>',21)])])}const m=a(o,[["render",r]]);export{g as __pageData,m as default};
